window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[306]={"id":"306","numero":306,"titre":"Tumeurs de l'ovaire","objectifs":[{"id":"306-1","rang":"A","rubrique":"Définition","titre":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","contenu":"<p>L'ovaire est une <span class=\"kw-def\">glande mixte</span> faite de plusieurs tissus aux fonctions complémentaires : la <span class=\"kw-def\">zone corticale</span> contient les follicules (ovocytes) et le stroma (cordons sexuels + cellules hormonosécrétantes), la <span class=\"kw-def\">zone médullaire</span> centrale est faite de tissu conjonctif lâche (nerfs, vaisseaux, lymphatiques), et la surface est recouverte par un épithélium <span class=\"kw-def\">mésothélial</span> qui explique que les tumeurs épithéliales représentent <span class=\"kw-chiffre\">~ 90 %</span> des tumeurs organiques.</p>\n\n      <table >\n        <thead>\n          <tr><th>Origine</th><th>Tumeurs bénignes</th><th>Tumeurs malignes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Épithéliale</strong><br>(<span class=\"kw-chiffre\">~ 90 %</span> des tumeurs organiques)</td>\n            <td>Cystadénome / adénofibrome <strong>séreux</strong>, <strong>mucineux</strong>, <strong>endométrioïde</strong> · tumeur de <strong>Brenner bénigne</strong></td>\n            <td>Adénocarcinome <strong>séreux haut <span class=\"kw-def\">grade</span></strong> (le + fréquent) · séreux bas grade · mucineux · endométrioïde · à <span class=\"kw-alerte\">cellules claires</span> · Brenner maligne · <strong>carcinosarcome</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Germinale</strong><br>(femme <span class=\"kw-clinique\">jeune</span>)</td>\n            <td><strong>Tératome mature</strong> = kyste dermoïde</td>\n            <td>Tératome <span class=\"kw-alerte\">immature</span> · <strong>dysgerminome</strong> · tumeur du sac vitellin (<em>yolk sac</em>) · <span class=\"kw-clinique\">carcinome</span> embryonnaire · choriocarcinome</td>\n          </tr>\n          <tr>\n            <td><strong>Cordons sexuels / stroma</strong></td>\n            <td><strong>Fibrome</strong> · thécome · fibrothécome</td>\n            <td>Tumeur de la <strong>granulosa</strong> (adulte / juvénile) · à cellules de <strong>Sertoli</strong> · à cellules de <strong>Leydig</strong> · <strong>Sertoli-Leydig</strong> (svt sécrétion hormonale)</td>\n          </tr>\n          <tr>\n            <td><strong>Métastatique</strong><br>(<span class=\"kw-chiffre\">~ 10 %</span> des malignes)</td>\n            <td>—</td>\n            <td><strong>Tumeur de Krukenberg</strong> (adénocarcinome <span class=\"kw-etio\">gastrique</span> à cellules indépendantes en bague à chaton) · cancers <span class=\"kw-etio\">colorectaux</span> · <span class=\"kw-etio\">sein</span> · <span class=\"kw-etio\">mélanomes</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Drapeau métastases.</strong> Les tumeurs métastatiques sont évoquées en cas de tumeurs <span class=\"kw-alerte\">bilatérales</span>. La tumeur de <strong>Krukenberg</strong> correspond à un adénocarcinome <span class=\"kw-etio\">gastrique</span> (plus rare : <span class=\"kw-etio\">colorectal</span>) à <span class=\"kw-alerte\">cellules indépendantes en bague à chaton</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 44 — <span class=\"kw-clinique\">Tuméfaction</span> pelvienne · 301 — Tumeur colon - rectum · 303 — Tumeur estomac · 312 — Tumeur sein · 41 — Endométriose</em></p>","frequence":1},{"id":"306-2","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types histologiques des tumeurs bénignes et malignes","contenu":"<p>La <span class=\"kw-def\">classification OMS 2020</span> affine la stratification de l'obj-0 en sous-types histologiques précis. L'enjeu n'est pas mnémotechnique : chaque sous-type a un <span class=\"kw-alerte\">pronostic</span> et une <span class=\"kw-ttt\">thérapeutique ciblée</span> propres (notamment les mutations <span class=\"kw-bio\">BRCA1/2</span>, l'<span class=\"kw-bio\">instabilité microsatellite</span> et les inhibiteurs de <span class=\"kw-ttt\">PARP</span>).</p>\n\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Bénin / Borderline</th><th>Malin</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Séreux</strong></td>\n            <td><strong>Bénin :</strong> cystadénome · adénofibrome · cystadénofibrome<br><strong>Borderline :</strong> séreuse borderline · micropapillaire</td>\n            <td>Adénocarcinome séreux <span class=\"kw-alerte\">haut grade</span> <em>(le + fréquent)</em> · adénocarcinome séreux bas <span class=\"kw-def\">grade</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mucineux</strong></td>\n            <td><strong>Bénin :</strong> cystadénome mucineux<br><strong>Borderline :</strong> mucineuse borderline</td>\n            <td>Adénocarcinome mucineux (expansif ou infiltratif)</td>\n          </tr>\n          <tr>\n            <td><strong>Endométrioïde</strong></td>\n            <td><strong>Bénin :</strong> cystadénome / adénofibrome endométrioïde<br><strong>Borderline :</strong> endométrioïde borderline</td>\n            <td>Adénocarcinome endométrioïde</td>\n          </tr>\n          <tr>\n            <td><strong>À cellules claires</strong></td>\n            <td><strong>Bénin :</strong> cystadénome<br><strong>Borderline :</strong> borderline à cellules claires</td>\n            <td>Adénocarcinome à <span class=\"kw-alerte\">cellules claires</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Tumeurs borderline (TBO).</strong> Représentent <span class=\"kw-chiffre\">10-20 %</span> des tumeurs épithéliales non bénignes. Âge médian inférieur de <span class=\"kw-chiffre\">-10 ans</span> aux tumeurs malignes (1/3 chez <span class=\"kw-clinique\">< 40 ans</span>). Excellent pronostic mais risque de récidive tardive (<span class=\"kw-chiffre\">> 20 ans</span>). <span class=\"kw-imagerie\">IRM pelvienne</span> essentielle, mais seule l'analyse <span class=\"kw-bio\">histologique</span> permet le diagnostic.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 293 — Anapath</em></p>","frequence":1},{"id":"306-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie et le pronostic des tumeurs bénignes et malignes","contenu":"<table >\n        <thead>\n          <tr><th>Type</th><th>Fréquence</th><th>Âge médian</th><th>Survie / <span class=\"kw-def\">Pronostic</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Bénignes</strong></td>\n            <td>Majorité des tumeurs ovariennes</td>\n            <td><span class=\"kw-chiffre\">~ 30 ans</span></td>\n            <td><strong>Bon <span class=\"kw-def\">pronostic</span>.</strong> Guéries après <span class=\"kw-ttt\">exérèse</span> chirurgicale pour fibrothécome, cystadénome séreux ou mucineux.</td>\n          </tr>\n          <tr>\n            <td><strong>Malignes</strong></td>\n            <td><span class=\"kw-chiffre\">5 200 nouveaux cas / an</span> (France, 2018)<br><span class=\"kw-alerte\">5ᵉ cancer féminin</span> · <span class=\"kw-alerte\">2ᵉ gynéco</span> après endomètre</td>\n            <td><span class=\"kw-chiffre\">65-68 ans</span></td>\n            <td><span class=\"kw-alerte\">4ᵉ cause de décès par cancer féminin</span> (1ʳᵉ par cancer gynéco)<br>Survie globale à<span class=\"kw-chiffre\"> 5 ans</span> : <span class=\"kw-chiffre\">45 %</span><br>FIGO I : <span class=\"kw-chiffre\">90 %</span> · FIGO ≥ III : <span class=\"kw-alerte\">< 40 %</span><br>Diagnostic <span class=\"kw-alerte\">tardif dans 75 %</span> des cas</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Facteurs pronostiques.</strong> Le facteur pronostique le plus important est la <strong>résécabilité de la maladie</strong> et le <strong>résidu tumoral post-opératoire</strong>. S'y associent l'<span class=\"kw-clinique\">âge</span>, l'<span class=\"kw-clinique\">état général</span>, le <span class=\"kw-bio\">type histologique</span>, le grade et la réponse à la chimiothérapie. Le pronostic est <span class=\"kw-ttt\">amélioré</span> par la PEC dans des centres experts (taux de résection R0 supérieur, accès aux essais cliniques).</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Pronostic global médiocre.</strong> Le diagnostic au <span class=\"kw-alerte\">stade tardif (75 % des cas)</span> explique la mortalité élevée du cancer de l'ovaire. La tumeur <strong>germinale</strong> est le type histologique de meilleur pronostic, car souvent découverte plus précocement chez la femme jeune.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers · 300 — Tumeur col-corps utérin · 312 — Tumeur sein · 124 — Ménopause - andropause</em></p>","frequence":1},{"id":"306-4","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître la physiopathologie des cancers de l’ovaire","contenu":"<p>Il existe <span class=\"kw-def\">deux théories complémentaires</span> sur l'origine du cancer de l'ovaire. Toutes deux convergent vers une <span class=\"kw-def\">origine multifocale</span>, ce qui explique la <span class=\"kw-alerte\">latence clinique</span> et la <span class=\"kw-alerte\">dissémination péritonéale précoce</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Théorie</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Origine tubaire</strong></td>\n            <td>La <span class=\"kw-clinique\">trompe de Fallope</span> serait le point de départ. Le <span class=\"kw-def\">carcinome séreux intra-épithélial tubaire (STIC)</span> est la 1ʳᵉ <span class=\"kw-clinique\">lésion</span> histologique des <span class=\"kw-bio\">carcinomes séreux haut grade</span> (= forme la plus fréquente). L'ovaire est secondairement envahi par des cellules dysplasiques d'origine tubaire.</td>\n          </tr>\n          <tr>\n            <td><strong>Cicatrisation ovarienne</strong><br>(<em>ovulation incessante</em>)</td>\n            <td>À chaque <span class=\"kw-clinique\">ovulation</span>, <span class=\"kw-alerte\">rupture</span> de l'épithélium de surface → prolifération cicatricielle → <span class=\"kw-bio\">kystes d'inclusion</span> → accumulation d'<span class=\"kw-bio\">anomalies génétiques</span> au fil des cycles. Justifie le rôle <span class=\"kw-ttt\">protecteur</span> des situations qui diminuent les ovulations (<span class=\"kw-clinique\">parité</span>, <span class=\"kw-clinique\">allaitement</span>, <span class=\"kw-ttt\">CO œstroprogestative</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Mode de dissémination</th><th>Cibles</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Loco-régional</strong><br>(péritoine ++)</td>\n            <td>Franchissement de la corticale ovarienne → dissémination très rapide vers les <span class=\"kw-clinique\">organes pelviens</span>, puis vers <span class=\"kw-alerte\">l'ensemble de la cavité péritonéale</span> au gré du flux du liquide péritonéal (= <strong>carcinose péritonéale</strong>).</td>\n          </tr>\n          <tr>\n            <td><strong>À distance</strong></td>\n            <td>Dissémination <span class=\"kw-clinique\">lymphatique</span> (ganglions pelviens + lomboaortiques), puis <span class=\"kw-clinique\">hématogène</span> (poumons, foie, cerveau).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pourquoi un diagnostic si tardif ?</strong> L'extension péritonéale précoce et silencieuse explique que <span class=\"kw-alerte\">3/4 des cancers sont diagnostiqués à un stade avancé</span> de carcinose. L'absence de <span class=\"kw-def\">dépistage</span> efficace aggrave ce retard.\n      </div>","frequence":2},{"id":"306-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux facteurs de risque/protecteurs associés au cancer de l’ovaire","contenu":"<div class=\"callout callout-danger\">\n        <strong>Pas de <span class=\"kw-def\">dépistage</span>.</strong> Il n'existe <span class=\"kw-alerte\">aucun dépistage efficace</span> du cancer de l'ovaire — d'où l'importance d'une <strong>consultation oncogénétique systématique</strong> dès qu'un cancer ovarien est diagnostiqué.\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>FdR génétiques (<span class=\"kw-chiffre\">10-20 %</span>)</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ATCD familial 1ᵉʳ degré</strong></td>\n            <td>Augmente le risque de <span class=\"kw-chiffre\">5 %</span> de développer un cancer de l'ovaire au cours de la vie.</td>\n          </tr>\n          <tr>\n            <td><strong>Mutations BRCA1 / BRCA2</strong></td>\n            <td><span class=\"kw-chiffre\">80 % des formes héréditaires</span> · cancers <span class=\"kw-clinique\">avant 60 ans</span> · <span class=\"kw-alerte\">consultation oncogénétique systématique</span> chez toute patiente atteinte · meilleur <span class=\"kw-def\">pronostic</span> (sensibilité aux <span class=\"kw-ttt\">inhibiteurs de PARP</span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Syndrome de Lynch</span></strong><br>(défaut <span class=\"kw-bio\">MMR</span> — <span class=\"kw-bio\">MSI-H</span>)</td>\n            <td>Concerne surtout colorectal + endomètre, mais aussi ovaire. À évoquer si cancer <span class=\"kw-clinique\">< 70 ans</span> ou histoire familiale évocatrice.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Autres FdR</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Extrinsèques</strong></td>\n            <td><span class=\"kw-etio\">Tabagisme</span> · <strong>exposition professionnelle à l'amiante</strong> (CIRC, 2012) · <span class=\"kw-etio\">surpoids</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Gynécologiques</strong></td>\n            <td>Augmentation du nombre de cycles : <span class=\"kw-clinique\">âge</span> · <span class=\"kw-clinique\">nulliparité</span> · <span class=\"kw-clinique\">puberté / règles précoces</span> · <span class=\"kw-clinique\">ménopause tardive</span>.<br><span class=\"kw-etio\">Iatrogène</span> : <span class=\"kw-ttt\">THM œstrogénique</span> · <span class=\"kw-ttt\">clomifène / FIV</span>.<br><span class=\"kw-clinique\">Infertilité</span> = FdR avéré.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Facteurs protecteurs</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Diminution du nb d'ovulations</strong></td>\n            <td>Grossesse · multiparité · allaitement · <span class=\"kw-ttt\">contraception orale œstroprogestative</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Suppression du tissu cible</strong></td>\n            <td>Ligature des trompes · <span class=\"kw-ttt\">salpingectomie bilatérale</span> (++ si <span class=\"kw-bio\">BRCA</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers · 35 — Anomalies cycle menstruel - métrorragie · 124 — Ménopause - andropause</em></p>","frequence":1},{"id":"306-6","rang":"B","rubrique":"Diagnostic","titre":"Connaître les indications de la cœlioscopie","contenu":"<p>La cœlioscopie est <span class=\"kw-def\">la voie privilégiée</span> pour obtenir la preuve histologique d'une tumeur ovarienne — qu'elle soit suspecte de bénignité (kystectomie / annexectomie) ou de malignité (<span class=\"kw-bio\">biopsies</span> de carcinose, annexectomie diagnostique). Elle est <span class=\"kw-alerte\">absolument contre-indiquée</span> pour la <span class=\"kw-bio\">biopsie</span> trans-pariétale ou trans-vaginale d'une <span class=\"kw-clinique\">masse</span> annexielle suspecte isolée (risque de dissémination).</p>\n\n      <table >\n        <thead>\n          <tr><th>Indication</th><th>Geste cœlioscopique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Kyste organique présumé bénin</strong></td>\n            <td><strong>Kystectomie</strong> (préserve le cortex ovarien) ou <strong>annexectomie</strong> selon âge / statut ménopausique.<br>Séquence : exploration complète péritonéale → <span class=\"kw-bio\">cytologie péritonéale</span> → kystectomie / annexectomie → extraction protégée → anapath.</td>\n          </tr>\n          <tr>\n            <td><strong>Tumeur suspecte de malignité</strong><br>(stades précoces FIGO 1-2)</td>\n            <td><strong>Annexectomie diagnostique</strong> (voire ovariectomie) <span class=\"kw-alerte\">uni- ou bilatérale</span>.<br>Éviter la kystectomie (<span class=\"kw-alerte\">risque de rupture et dissémination péritonéale</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Stades avancés</strong><br>(FIGO 3-4, carcinose)</td>\n            <td><strong>Cœlioscopie diagnostique</strong> : <span class=\"kw-bio\">biopsies</span> de nodules de carcinose + évaluation de la résécabilité (scores reproductibles) + recherche de CI au débulking (<span class=\"kw-ttt\">infiltration</span> mésentère, pédicule hépatique, grêle).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Urgence</span> — torsion d'annexe</strong></td>\n            <td><span class=\"kw-alerte\">< 6 h idéalement</span> : cœlio en urgence (détorsion + kystectomie). <span class=\"kw-ttt\">Détorsion conservatrice possible au-delà</span> si reprise de coloration peropératoire (recommandation CNGOF). Conservation ovarienne <em>même si aspect initialement nécrotique</em>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège EDN classique.</strong> En cas de tumeur <strong>volumineuse</strong> (<span class=\"kw-chiffre\">> 10 cm</span>) ou de diagnostic incertain, on préfère la <span class=\"kw-ttt\">laparotomie</span> à la cœlioscopie — pour <span class=\"kw-alerte\">éviter de rompre la tumeur</span>. Idem si CI à la cœlio (insuffisance respiratoire ou cardiaque, ATCD chirurgicaux lourds : péritonites, cancers coliques, Crohn).\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>CI absolue.</strong> Pas de <span class=\"kw-alerte\">biopsie trans-pariétale ou trans-vaginale</span> d'une masse annexielle suspecte isolée — risque de <span class=\"kw-ci\">dissémination tumorale</span> par le trajet de ponction. La preuve histologique passe par la cœlio (ou la laparotomie).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 44 — Tuméfaction pelvienne · 40 — Algies pelviennes · 269 — <span class=\"kw-clinique\">Douleur abdominale</span> aiguë</em></p>","frequence":4},{"id":"306-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de l’imagerie d’une tumeur de l’ovaire","contenu":"<p>L'imagerie pelvienne suit une <span class=\"kw-def\">hiérarchie stricte</span> selon le contexte. L'<span class=\"kw-imagerie\">échographie pelvienne</span> est l'examen de 1ʳᵉ intention devant toute suspicion de <span class=\"kw-clinique\">masse</span> pelvienne, complétée par l'<span class=\"kw-imagerie\">IRM</span> en cas d'incertitude, puis par la <span class=\"kw-imagerie\">TDM-TAP</span> pour le <span class=\"kw-def\">bilan d'extension</span> après <span class=\"kw-def\">diagnostic positif</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> pelvienne</strong><br>(1ʳᵉ intention)</td>\n            <td>Voie <span class=\"kw-imagerie\">sus-pubienne vessie pleine</span> + voie <span class=\"kw-imagerie\">endovaginale vessie vide</span> + <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">échographie</span> abdominale</span> ± <span class=\"kw-imagerie\">écho-doppler couleur</span>.<br>Classe la tumeur en <strong>kyste fonctionnel</strong> <span class=\"kw-bio\">vs</span> <strong>kyste organique</strong> <span class=\"kw-bio\">vs</span> <strong><span class=\"kw-def\">critères de</span> malignité</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> abdomino-pelvienne</strong></td>\n            <td><strong>Indications :</strong> <span class=\"kw-clinique\">masse</span> ovarienne indéterminée (caractérisation par <span class=\"kw-imagerie\">diffusion</span> + perfusion) · <span class=\"kw-def\">bilan d'extension</span> locorégional des formes localisées · suspicion de TBO (intérêt majeur).<br><strong>Non-indication :</strong> pas d'intérêt si <span class=\"kw-imagerie\">échographie</span> suspecte d'emblée une maladie avancée avec carcinose (on passe direct au <span class=\"kw-imagerie\">TDM</span>-TAP).<br><strong><span class=\"kw-def\">Classification</span> <span class=\"kw-def\">O-RADS</span></strong> (<em>Ovarian-Adnexal Reporting & Data System</em>) :<br><strong>O-RADS 1-2</strong> = presque toujours bénin → <span class=\"kw-ttt\">surveillance possible</span><br><strong>O-RADS 3</strong> = risque faible → <span class=\"kw-ttt\">avis spécialisé</span><br><strong>O-RADS 4-5</strong> = <span class=\"kw-alerte\">tumeur borderline ou invasive suspectée</span> → <span class=\"kw-imagerie\">IRM</span> injectée + <span class=\"kw-ttt\">prise en charge chirurgicale</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> thoraco-abdomino-pelvien</strong><br>(<span class=\"kw-imagerie\">TDM</span>-TAP)</td>\n            <td><strong>Systématique</strong> pour le <span class=\"kw-def\">bilan d'extension</span> après <span class=\"kw-def\">diagnostic positif</span>. Apprécie l'importance et la distribution de la <span class=\"kw-alerte\">carcinose péritonéale</span> (++ étage supérieur de l'abdomen), explore les chaînes ganglionnaires rétropéritonéales / pelviennes / lomboaortiques. Coupes thoraciques : recherche d'<span class=\"kw-alerte\">épanchement pleural</span> (fréquent <span class=\"kw-def\">stade</span> IV) et de ganglions médiastinaux ou sus-claviculaires.</td>\n          </tr>\n          <tr>\n            <td><strong>Optionnels</strong></td>\n            <td><strong><span class=\"kw-imagerie\"><span class=\"kw-imagerie\">TEP</span>-<span class=\"kw-imagerie\">TDM</span></span> 18FDG :</strong> complément du <span class=\"kw-imagerie\">TDM</span> pour les <span class=\"kw-chiffre\">stades avancés</span> ou les <span class=\"kw-chiffre\">récidives</span> (suspicion de rechute avec <span class=\"kw-imagerie\">TDM</span> normal).<br><strong>Imagerie mammaire</strong> (<span class=\"kw-imagerie\">mammographie</span> + écho) : éliminer un cancer du sein concomitant en cas de carcinose péritonéale avec masses annexielles.<br><strong><span class=\"kw-imagerie\">Endoscopie</span> digestive</strong> (<span class=\"kw-imagerie\">FOGD</span> + <span class=\"kw-imagerie\">coloscopie</span>) : éliminer une origine digestive primitive si <span class=\"kw-bio\">CA 19-9</span> augmenté ou image <span class=\"kw-imagerie\">TDM</span>-TAP suspecte.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Critères échographiques de malignité</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Taille de la <span class=\"kw-clinique\">masse</span></strong></td>\n            <td><span class=\"kw-alerte\">> 7 cm</span> (cut-off rang A).</td>\n          </tr>\n          <tr>\n            <td><strong>Présence de cloisons</strong></td>\n            <td>Caractère <span class=\"kw-alerte\">multiloculaire</span> · cloisons épaisses (<span class=\"kw-chiffre\">> 3 mm</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Parois épaissies</strong></td>\n            <td>Irrégularités des parois interne ou externe — <em>signe majeur</em> de malignité.</td>\n          </tr>\n          <tr>\n            <td><strong>Composantes solides</strong></td>\n            <td><span class=\"kw-alerte\">Végétations endo/exo-kystiques</span> plus ou moins épaisses et confluentes.</td>\n          </tr>\n          <tr>\n            <td><strong>Vascularisation <span class=\"kw-imagerie\">doppler</span></strong></td>\n            <td><span class=\"kw-alerte\">Hypervascularisation</span> (néovascularisation) + <span class=\"kw-alerte\">diminution de la résistivité</span> (vitesse de circulation sanguine).</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td><span class=\"kw-alerte\">Ascite</span> · <span class=\"kw-alerte\">adénopathies</span> · <span class=\"kw-alerte\">bilatéralité</span> · nodules de carcinose (peu visibles en écho, mieux vus en <span class=\"kw-imagerie\">TDM</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>CAT échographique synthétique.</strong> <span class=\"kw-def\">Critères de</span> bénignité tous présents (<span class=\"kw-chiffre\">< 7 cm</span>, uniloculaire, anéchogène pur, parois fines, pas de végétation, pas de vascularisation pathologique, pas d'ascite) → <span class=\"kw-ttt\">surveillance écho à M1-M3</span>. Persistance à<span class=\"kw-chiffre\"> 3 mois</span> → kyste organique. Critère(s) suspects → <span class=\"kw-imagerie\">IRM</span> + <span class=\"kw-bio\">marqueurs</span>. Carcinose / ascite → <span class=\"kw-imagerie\">TDM-TAP injecté</span>.\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>Piège kyste dermoïde.</strong> Diagnostic souvent fait à l'écho seule grâce à l'aspect hétérogène + zones hyperéchogènes (cheveux, dents) + <strong>protubérance de Rokitanski</strong>. Le <span class=\"kw-imagerie\">TDM</span> aide en montrant le <span class=\"kw-imagerie\">contenu graisseux caractéristique</span> + calcifications. Mais <span class=\"kw-alerte\">risque élevé de torsion d'annexe</span> (kyste lourd).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 44 — Tuméfaction pelvienne · 40 — Algies pelviennes</em></p>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/ovarian-tumours","label":"Radiopaedia : Ovarian tumours"},{"href":"https://radiopaedia.org/articles/ovary","label":"Radiopaedia : Ovary"},{"href":"https://radiopaedia.org/articles/ovarian-cyst-2","label":"Radiopaedia : Ovarian cyst 2"},{"href":"https://radiopaedia.org/articles/ovarian-torsion","label":"Radiopaedia : Ovarian torsion"},{"href":"https://radiopaedia.org/articles/hemorrhagic-ovarian-cyst-2","label":"Radiopaedia : Hemorrhagic ovarian cyst 2"}]},{"id":"306-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt diagnostique et pronostique de l’anapath","contenu":"<div class=\"callout callout-danger\">\n        <strong>Spécificité cancer de l'ovaire.</strong> C'est l'un des <span class=\"kw-alerte\">rares cancers</span> dont le diagnostic n'est <span class=\"kw-alerte\">pas obtenu en pré-opératoire</span> — le diagnostic est <span class=\"kw-def\">chirurgical</span> dans la majorité des cas. Recommandé <span class=\"kw-alerte\">avant toute chimiothérapie</span>.\n      </div>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Stade</span> FIGO</th><th>Modalité de prélèvement</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Stades précoces</strong><br>(FIGO 1-2)</td>\n            <td>Exploration chirurgicale → <strong>annexectomie diagnostique</strong> + anapath.<br><strong>< 10 cm :</strong> <span class=\"kw-ttt\">cœlioscopie</span> privilégiée.<br><strong><span class=\"kw-chiffre\">> 10 cm</span> ou diagnostic incertain :</strong> <span class=\"kw-ttt\">laparotomie</span> (éviter <span class=\"kw-alerte\">rupture</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Stades avancés</strong><br>(FIGO 3-4)</td>\n            <td><strong>Cœlioscopie diagnostique</strong> pour <span class=\"kw-bio\">biopsies</span> multiples des nodules de carcinose.</td>\n          </tr>\n          <tr>\n            <td><strong>Patiente non opérable</strong></td>\n            <td><strong><span class=\"kw-bio\">Biopsie</span> sous radiologie interventionnelle</strong> (percutanée sous <span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">échographie</span> d'un <span class=\"kw-clinique\">nodule</span> de carcinose).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Type de prélèvement</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic positif</span></strong></td>\n            <td>Matériel <strong>biopsique</strong> (et <span class=\"kw-alerte\">non cytologique</span>) · <span class=\"kw-bio\">biopsies</span> <span class=\"kw-bio\">multiples</span> et de <span class=\"kw-bio\">bonne taille</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Mutations somatiques</strong><br>(sur la tumeur)</td>\n            <td><strong>BRCA1 / BRCA2 systématique</strong> : si mutation → conseil oncogénétique + <span class=\"kw-ttt\">inhibiteurs de PARP</span> adjuvant.<br><strong><span class=\"kw-def\">Score</span> HRD</strong> (<em>Homologous Recombination Deficiency</em>) : recherché si <span class=\"kw-bio\">BRCA sauvage</span> — conditionne l'éligibilité aux <span class=\"kw-ttt\">PARPi (olaparib, niraparib)</span> en 1ʳᵉ ligne.<br><strong>Instabilité microsatellites (Lynch) :</strong> non systématique, à réaliser si cancer <span class=\"kw-chiffre\">< 70 ans</span> ou histoire personnelle / familiale évocatrice.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 293 — Anapath · 292 — Diagnostic des cancers</em></p>","frequence":1},{"id":"306-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux marqueurs sériques et leur bon usage dans les tumeurs de l’ovaire","contenu":"<p>Le choix des marqueurs sériques dépend du contexte clinique (femme jeune / âgée) et de la suspicion histologique (épithéliale / germinale / cordon sexuel). Le <span class=\"kw-bio\">CA 125</span> est le marqueur de référence du cancer épithélial — mais ni assez sensible ni assez spécifique pour porter le diagnostic à lui seul.</p>\n\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Marqueurs à doser</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Suspicion de cancer épithélial</strong><br>(1ʳᵉ intention)</td>\n            <td><strong><span class=\"kw-bio\">CA 125</span></strong> (assez spécifique) · <strong><span class=\"kw-bio\">CA 19-9</span></strong> (souvent élevé dans les formes mucineuses) · <strong><span class=\"kw-bio\">ACE</span></strong> (moins spécifique).</td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion tumeur germinale</strong><br>(femme <span class=\"kw-clinique\">jeune</span>)</td>\n            <td><strong><span class=\"kw-bio\">LDH</span> + α-fœtoprotéine</strong> (élevés dans les dysembryomes) · <strong>hCG</strong> (élevés dans les choriocarcinomes).</td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion tumeur des cordons sexuels</strong><br>(signes d'hyperœstrogénie ou tumeur de la granulosa)</td>\n            <td><strong>Estradiol + AMH + inhibine B</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Masse</span> ovarienne indéterminée à l'imagerie</strong></td>\n            <td><strong>HE4</strong> (<em>Human Epididymal Protein 4</em>) — peu utilisé, <span class=\"kw-alerte\">non remboursé</span>. S'interprète selon le <span class=\"kw-def\">score ROMA</span> (statut ménopausique + <span class=\"kw-bio\">CA 125</span> + <span class=\"kw-bio\">HE4</span>) — cut-off : <span class=\"kw-chiffre\">11,4 % préménopause</span> · <span class=\"kw-chiffre\">29,9 % postménopause</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-bio\">CA 125</span> : pièges à connaître.</strong> <strong>Sensibilité imparfaite</strong> : <span class=\"kw-alerte\">faux négatifs possibles</span> (un <span class=\"kw-bio\">CA 125 normal n'élimine pas un cancer</span>). <strong>Spécificité imparfaite</strong> : c'est aussi un <span class=\"kw-alerte\">marqueur d'irritation péritonéale</span> (<span class=\"kw-clinique\">endométriose</span>, <span class=\"kw-clinique\">infection</span>, autres carcinomes non ovariens). Donc <span class=\"kw-alerte\">il n'est pas recommandé</span> de se fonder uniquement sur le <span class=\"kw-bio\">CA 125</span> sérique pour évaluer la résécabilité d'une carcinose.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Suivi</span> post-traitement.</strong> Si <span class=\"kw-bio\">CA 125 < 10 UI/mL</span> après traitement, toute élévation <span class=\"kw-alerte\">> 20 UI/mL</span> contrôlée à<span class=\"kw-chiffre\"> 15 jours</span> est suspecte de récidive — peut précéder les signes cliniques. La décroissance des marqueurs juge en partie l'efficacité du traitement.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 290 — Epidémiologie cancers</em></p>","frequence":2}],"astuces":[],"strategie":{"redflags":"<p><strong>✅ <span class=\"kw-def\">Critères de</span> bénignité (tous requis)</strong></p><p>→ Si TOUS réunis : contrôle écho à <span class=\"kw-chiffre\">3 mois</span> (exclure un kyste fonctionnel). Persistance = origine organique.</p><ul><li>Image <span class=\"kw-clinique\">uniloculaire</span> ou pluriloculaire à cloison <span class=\"kw-chiffre\">très fine (&lt; 3 mm)</span></li><li><span class=\"kw-clinique\">Absence de zone solide</span> (pas de végétation), <span class=\"kw-clinique\">paroi fine</span></li><li>Vascularisation <span class=\"kw-clinique\">périphérique régulière</span>, index de résistance <span class=\"kw-chiffre\">&gt; 0,50</span></li><li>Kyste <span class=\"kw-chiffre\">&lt; 7 cm</span>, <span class=\"kw-clinique\">absence d’ascite</span></li></ul><p><strong>🔴 <span class=\"kw-def\">Critères de</span> malignité</strong></p><p>→ Absence de <span class=\"kw-def\">critères de</span> bénignité : <span class=\"kw-imagerie\">IRM</span> ou <span class=\"kw-ttt\">cœlioscopie</span> s’impose.</p><ul><li><span class=\"kw-clinique\">Masse</span> <span class=\"kw-alerte\">solide ou mixte</span>, taille <span class=\"kw-chiffre\">≥ 7 cm</span></li><li><span class=\"kw-alerte\">Végétations</span> endo/exo-kystiques, cloisons épaisses, parois épaissies, contours irréguliers</li><li>Doppler : <span class=\"kw-alerte\">hypervascularisation</span> (néovascularisation) + <span class=\"kw-alerte\">baisse de la résistivité</span></li><li><span class=\"kw-alerte\">Bilatéralité</span>, <span class=\"kw-alerte\">ascite</span>, carcinose péritonéale, <span class=\"kw-clinique\">adénopathies</span></li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/ovarian-tumours","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/ovary","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/ovarian-cyst-2","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/ovarian-torsion","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/hemorrhagic-ovarian-cyst-2","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Masse ovarienne / kyste découvert(e) — β-hCG (éliminer une GEU si non ménopausée) → échographie pelvienne de 1ʳᵉ ligne","detail":"<h4>Démarche diagnostique devant une <span class=\"kw-clinique\">masse</span> ovarienne — De l’<span class=\"kw-imagerie\">échographie</span> de 1ʳᵉ ligne à la preuve histologique</h4>","branches":[{"to":"q-fonctionnel","label":"Kyste fonctionnel (uniloculaire anéchogène, ≤ 7 cm)","color":"green"},{"to":"q-organique","label":"Kyste organique / écho indéterminée (pas tous les critères de bénignité)","color":"amber"},{"to":"q-malin","label":"Signes de malignité (végétations, solide, ascite, bilatéralité…)","color":"red"}]},{"id":"q-fonctionnel","kind":"decision","label":"Évolution au contrôle écho M1–M3 ? — Aucun blocage ovarien si tous les critères de bénignité sont réunis","branches":[{"to":"t-fonctionnel-ok","label":"Disparition","color":"green"},{"to":"t-fonctionnel-persist","label":"Persistance à 3 mois","color":"amber"}]},{"id":"t-fonctionnel-ok","kind":"terminal","label":"Kyste fonctionnel confirmé","color":"green","detail":"<h4>Conduite</h4><ul><li>Disparition au contrôle = kyste fonctionnel : <strong>aucun geste</strong>, fin de la <span class=\"kw-def\">surveillance</span>.</li></ul>"},{"id":"t-fonctionnel-persist","kind":"terminal","label":"Origine organique → cœlioscopie","color":"amber","detail":"<h4>Conduite</h4><ul><li>Persistance = origine <span class=\"kw-def\">organique</span> probable.</li></ul><h4>Geste</h4><ul><li><span class=\"kw-def\">Surveillance</span> ou ablation par <span class=\"kw-ttt\">cœlioscopie</span> (kystectomie ou annexectomie selon l’âge et le risque).</li></ul>"},{"id":"q-organique","kind":"decision","label":"IRM pelvienne — Meilleur examen pour caractériser une tumeur ovarienne isolée — recommandée après l’échographie","branches":[{"to":"t-organique-benin","label":"Bénin confirmé (tous critères de bénignité)","color":"green"},{"to":"t-organique-coelio","label":"Indéterminé / organique","color":"amber"}]},{"id":"t-organique-benin","kind":"terminal","label":"Surveillance ou geste cœlioscopique","color":"green","detail":"<h4>Conduite</h4><ul><li>Contrôle à<span class=\"kw-chiffre\"> 3 mois</span> (exclure un kyste fonctionnel) puis <span class=\"kw-def\">surveillance</span>, ou ablation par <span class=\"kw-ttt\">cœlioscopie</span> (kystectomie / annexectomie).</li></ul>"},{"id":"t-organique-coelio","kind":"terminal","label":"Geste sous cœlioscopie","color":"amber","detail":"<h4>Geste</h4><ul><li><span class=\"kw-ttt\">Kystectomie</span> ou <span class=\"kw-ttt\">annexectomie</span> selon l’âge et le risque de malignité.</li></ul><h4>Extemporané</h4><ul><li>Réservé aux kystes suspects d’être <span class=\"kw-alerte\">borderline</span> (éviter une réintervention de <span class=\"kw-def\">stadification</span>).</li></ul>"},{"id":"q-malin","kind":"decision","label":"Bilan de malignité — IRM abdomino-pelvienne + marqueurs ± TDM-TAP","branches":[{"to":"t-malin","label":"Suspicion confirmée → orientation","color":"red"}]},{"id":"t-malin","kind":"terminal","label":"Centre spécialisé → laparotomie médiane de stadification","color":"red","detail":"<h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">IRM abdomino-pelvienne</span> (séquences diffusion + perfusion)</li><li><span class=\"kw-imagerie\">TDM-TAP</span> injectée si ascite / carcinose : atteinte hépatique, <span class=\"kw-clinique\">adénopathies</span> lombo-aortiques et pelviennes</li></ul><h4>Marqueurs</h4><ul><li>Épithélial : <span class=\"kw-bio\">CA-125</span> + <span class=\"kw-bio\">ACE</span> + <span class=\"kw-bio\">CA 19-9</span></li><li>Germinal (femme jeune) : <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">α-fœtoprotéine</span>, <span class=\"kw-bio\">hCG</span></li><li>Granulosa : <span class=\"kw-bio\">estradiol</span>, <span class=\"kw-bio\">AMH</span>, <span class=\"kw-bio\">inhibine B</span></li></ul><h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li><span class=\"kw-ttt\">Laparotomie médiane</span> = <span class=\"kw-def\">stadification</span> + traitement</li><li>⚠️ Éviter cœlioscopie / kystectomie (risque de <span class=\"kw-alerte\">rupture</span> et dissémination péritonéale)</li><li>Orienter vers un centre chirurgical spécialisé des cancers de l’ovaire</li></ul><h4>Bilan d’extension</h4><ul><li><span class=\"kw-imagerie\">TDM-TAP</span> systématique (carcinose)</li><li><span class=\"kw-imagerie\">TEP-TDM</span> si <span class=\"kw-def\">stade</span> avancé ou récidive</li></ul><h4>Renvoi</h4><ul><li>292 (diagnostic des cancers) · 290 (<span class=\"kw-def\">épidémiologie</span> des cancers)</li></ul>"}]},"cards":[{"i":"2420a4790f1a","n":306,"o":"306-1","u":"Définition","t":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","q":"Quels sont les principaux types de tumeurs ovariennes primitives bénignes et malignes d'origine germinale ?","a":"<p>Les principales tumeurs ovariennes primitives d'origine germinale, plus fréquentes chez la <strong>femme jeune</strong>, sont :</p><ul><li>Tumeurs bénignes : le <strong>tératome mature</strong> (également appelé <strong>kyste dermoïde</strong>).</li><li>Tumeurs malignes : le <strong>tératome immature</strong>, le <strong>dysgerminome</strong>, la <strong>tumeur du sac vitellin</strong> (yolk sac), le <strong>carcinome embryonnaire</strong>, et le <strong>choriocarcinome</strong>.</li></ul>"},{"i":"3e25bb51eca8","n":306,"o":"306-1","u":"Définition","t":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","q":"Quelle est l'origine tissulaire majoritaire des tumeurs ovariennes primitives et quels sont les principaux types de tumeurs bénignes et malignes qui en dérivent ?","a":"<p>L'origine tissulaire majoritaire des tumeurs ovariennes primitives est <strong>épithéliale</strong>, représentant environ <strong>90 %</strong> des tumeurs organiques. Les principaux types incluent :</p><ul><li>Tumeurs bénignes : <strong>cystadénome / adénofibrome séreux, mucineux, endométrioïde</strong>, et la <strong>tumeur de Brenner bénigne</strong>.</li><li>Tumeurs malignes : <strong>adénocarcinome séreux haut grade</strong> (le plus fréquent), séreux bas grade, mucineux, endométrioïde, à cellules claires, Brenner maligne, et le <strong>carcinosarcome</strong>.</li></ul>"},{"i":"807ee03e9d06","n":306,"o":"306-1","u":"Définition","t":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","q":"Qu'est-ce qu'une tumeur de Krukenberg et quelle est son origine ?","a":"<p>La <strong>tumeur de Krukenberg</strong> est une tumeur ovarienne métastatique, représentant environ <strong>10 %</strong> des tumeurs ovariennes malignes. Elle est caractérisée histologiquement par des <strong>cellules indépendantes en bague à chaton</strong>. Son origine la plus fréquente est un <strong>adénocarcinome gastrique</strong>, mais des origines <strong>colorectales</strong> ou mammaires sont également possibles.</p>"},{"i":"81396f334aed","n":306,"o":"306-1","u":"Définition","t":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","q":"Quels sont les principaux types de tumeurs ovariennes primitives bénignes et malignes d'origine des cordons sexuels / stroma ?","a":"<p>Les principales tumeurs ovariennes primitives dérivant des cordons sexuels / stroma sont :</p><ul><li>Tumeurs bénignes : le <strong>fibrome</strong>, le <strong>thécome</strong>, et le <strong>fibrothécome</strong>.</li><li>Tumeurs malignes : la <strong>tumeur de la granulosa</strong> (adulte / juvénile), les tumeurs à <strong>cellules de Sertoli</strong>, à <strong>cellules de Leydig</strong>, et les tumeurs à <strong>cellules de Sertoli-Leydig</strong> (souvent associées à une sécrétion hormonale).</li></ul>"},{"i":"b61b486d8558","n":306,"o":"306-5","u":"Diagnostic positif","t":"Connaître les principaux facteurs de risque/protecteurs associés au cancer de l’ovaire","q":"Quels sont les principaux facteurs protecteurs contre le cancer de l'ovaire ?","a":"<p>Les principaux facteurs protecteurs contre le cancer de l'ovaire sont :</p><ul><li>Ceux qui diminuent le nombre d'ovulations : la <strong>grossesse</strong>, la <strong>multiparité</strong>, l'<strong>allaitement</strong>, la <strong>contraception orale œstroprogestative</strong>.</li><li>Ceux qui suppriment le tissu cible : la <strong>ligature des trompes</strong> et la <strong>salpingectomie bilatérale</strong> (particulièrement si mutation BRCA).</li></ul>"},{"i":"c7326b1e1f7e","n":306,"o":"306-5","u":"Diagnostic positif","t":"Connaître les principaux facteurs de risque/protecteurs associés au cancer de l’ovaire","q":"Quels sont les principaux facteurs de risque génétiques du cancer de l'ovaire à rechercher ?","a":"<p>Les principaux facteurs de risque génétiques du cancer de l'ovaire sont :</p><ul><li>Des <strong>antécédents familiaux de 1er degré</strong>, augmentant le risque à 5% au cours de la vie.</li><li>Des <strong>mutations BRCA1/BRCA2</strong> (80% des formes héréditaires, avant 60 ans, meilleur pronostic avec les inhibiteurs de PARP).</li><li>Le <strong>syndrome de Lynch</strong> (défaut MMR - MSI-H), impliquant principalement cancer colorectal et endomètre, mais aussi ovaire.</li></ul>"},{"i":"fce4e76ca714","n":306,"o":"306-5","u":"Diagnostic positif","t":"Connaître les principaux facteurs de risque/protecteurs associés au cancer de l’ovaire","q":"Quels sont les facteurs de risque extrinsèques et gynécologiques du cancer de l'ovaire ?","a":"<p>Les facteurs de risque extrinsèques et gynécologiques du cancer de l'ovaire sont :</p><ul><li><strong>Extrinsèques :</strong> le <strong>tabagisme</strong>, l'exposition professionnelle à l'<strong>amiante</strong>, le <strong>surpoids</strong>.</li><li><strong>Gynécologiques :</strong> l'augmentation du nombre de cycles (âge, <strong>nulliparité</strong>, puberté/règles précoces, ménopause tardive), l'<strong>infertilité</strong>, et ceux d'origine iatrogène (<strong>THM œstrogénique</strong>, clomifène/FIV).</li></ul>"}]};